/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: AdminPagesPage
 * Internal
 *   Types: PageSlug, PlacementTarget
 *   Functions: eligibleOrder, Pages, PageItems
 *   Constants: PageOrderList, PageOrderNotice, PageOrderApproval
 * @end-catalog */

import { lazy, Suspense, useEffect, useRef, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { RefreshCw } from 'lucide-react';
import { ModalDialog } from '../../components/ModalDialog';
import { AdminGate, useAdminAccess } from './AdminAccess';
import { useAdminPageText } from './adminPageText';
import { AdminNav } from './AdminNav';
import { adminEndpointRequest } from './adminTransport';
import { pageResponse, pageMutationResponse, type AdminPage } from './pageApi';
import type { PageOrderReview } from './PageOrderList';
import { adminWorkspace } from './adminWorkspace';
import { PagePlacementMetadata, PagePlacementRow, PagePlacementTypeIcon, PagePlacementVisibility, PageReferenceWarning } from './PagePlacementRow';
import { useAdminCommand } from './useAdminCommand';
import shared from './adminStyles';
import styles from './AdminPagesPage.module.css';

const PageOrderList = lazy(() => import('./PageOrderList').then(module => ({ default: module.PageOrderList })));
const PageOrderNotice = lazy(() => import('./PageOrderList').then(module => ({ default: module.PageOrderNotice })));
const PageOrderApproval = lazy(() => import('./PageOrderList').then(module => ({ default: module.PageOrderApproval })));

type PageSlug = AdminPage['slug'];
/** An ambiguous legacy identity cannot enter a local draft through either entry or refresh. */
const eligibleOrder = (page: AdminPage) => page.items.length > 1 && new Set(page.items.map(item => item.itemId)).size === page.items.length;
/** Approval and recovery copy describe the same captured placement and page revision. */
interface PlacementTarget { item: AdminPage['items'][number]; index: number; visibility: 'public' | 'hidden'; revision: string }

/** Selects a Page without prefetching private configuration or counts for the other Page. */
function Pages() {
  const t = useAdminPageText(), [slug, setSlug] = useState<PageSlug>('home');
  return <section className={shared.page + ' ' + styles.page}><AdminNav />
    <header className={styles.header}><h1 className={styles.title}>{t('catalog.pages')}</h1><p>{t('pages.subtitle')}</p></header>
    <PageItems key={slug} slug={slug} onSelect={setSlug} />
  </section>;
}

/** Keeps each Page's commands independent and retains approval context for uncertain writes. */
function PageItems({ slug, onSelect }: { slug: PageSlug; onSelect: (value: PageSlug) => void }) {
  const t = useAdminPageText(), access = useAdminAccess(), client = useQueryClient();
  const [target, setTarget] = useState<PlacementTarget | null>(null);
  const contextKey = 'page-visibility-target:' + slug;
  const [operationTarget, setOperationTarget] = useState(() => adminWorkspace.buffer<PlacementTarget>(contextKey) ?? null);
  const orderKey = 'page-order-target:' + slug;
  const [operationOrder, setOperationOrder] = useState(() => adminWorkspace.buffer<PageOrderReview>(orderKey) ?? null);
  const [draft, setDraft] = useState<PageOrderReview | null>(null), [orderConfirm, setOrderConfirm] = useState(false);
  const [dragging, setDragging] = useState(false), [saved, setSaved] = useState(false);
  const orderAction = useRef<HTMLButtonElement>(null), orderRecovery = useRef<HTMLButtonElement>(null);
  const active = useRef(true), refreshAttempt = useRef(0);
  useEffect(() => { active.current = true; return () => { active.current = false; refreshAttempt.current++; }; }, []);
  const cancel = useRef<HTMLButtonElement>(null);
  const returnFocus = useRef<HTMLElement>(null), pendingFocus = useRef<HTMLElement>(null);
  const queryKey = ['admin-imports', access.viewerId, access.epoch, access.generation, 'page', slug];
  const command = useAdminCommand('page:' + slug, pageMutationResponse.refine(value => value.page.slug === slug));
  const query = useQuery({ queryKey, queryFn: ({ signal }) => adminEndpointRequest('/pages/' + slug, pageResponse.refine(value => value.page.slug === slug), { signal }), retry: false, gcTime: 0 });
  useEffect(() => {
    if (!command.result) return;
    void client.cancelQueries({ queryKey });
    client.setQueryData(queryKey, { page: command.result.page });
    adminWorkspace.forget(contextKey); setOperationTarget(null);
    if (operationOrder) { setSaved(true); setDraft(null); setOrderConfirm(false); }
    adminWorkspace.forget(orderKey); setOperationOrder(null);
    command.command.acknowledge(); void query.refetch();
  }, [command.result]);
  useEffect(() => {
    if (!command.error || command.intent) return;
    adminWorkspace.forget(contextKey); setOperationTarget(null);
  }, [command.error, command.intent]);
  useEffect(() => {
    if (command.error && operationOrder) {
      setOrderConfirm(false);
      if (command.intent || command.error === 'reload') setDraft(null);
      // The frozen-operation recovery controls remain usable after its modal closes.
      const timer = window.setTimeout(() => orderRecovery.current?.focus(), 0);
      return () => window.clearTimeout(timer);
    }
  }, [command.error, operationOrder]);
  const locked = command.running || Boolean(command.intent) || !access.catalogVisibility || access.reloadRequired;
  const stale = Boolean(target && target.revision !== query.data?.page.revision);
  const orderFailure = Boolean(operationOrder && command.error && !command.intent);
  const orderStale = Boolean(draft && (draft.revision !== query.data?.page.revision || orderFailure && command.error === 'conflict'));
  useEffect(() => { if (orderConfirm && orderStale) orderRecovery.current?.focus(); }, [orderConfirm, orderStale]);
  const page = query.data?.page;
  const canOrder = Boolean(page && eligibleOrder(page));
  const presentation = { text: t, styles, renderIcon: (item: AdminPage['items'][number], size: number) => <PagePlacementTypeIcon item={item} size={size} /> };
  const changed = draft ? draft.items.filter((item, index) => draft.originalIds[index] !== item.itemId).length : 0;
  /** Begins from a confirmed snapshot, never an uncertain operation's frozen payload. */
  function beginOrder(value: AdminPage) {
    if (!eligibleOrder(value)) return;
    setSaved(false); setTarget(null); setDragging(false);
    setDraft({ items: [...value.items], originalIds: value.items.map(item => item.itemId), revision: value.revision });
  }
  function cancelOrder() {
    if (command.running || command.intent) return;
    refreshAttempt.current++; setDraft(null); setOrderConfirm(false); setDragging(false);
    adminWorkspace.forget(orderKey); setOperationOrder(null); command.command.settle();
    const guard = adminWorkspace.capture();
    window.requestAnimationFrame(() => { if (active.current && adminWorkspace.current(guard)) orderAction.current?.focus(); });
  }
  /** Explicitly discards a stale draft before reading a replacement, fenced against route/account changes. */
  async function restartOrder() {
    if (command.running || command.intent) return;
    cancelOrder(); const attempt = ++refreshAttempt.current, guard = adminWorkspace.capture();
    const result = await query.refetch();
    if (active.current && attempt === refreshAttempt.current && adminWorkspace.current(guard) && result.isSuccess && eligibleOrder(result.data.page)) beginOrder(result.data.page);
  }
  const recoveryActions = <><button type="button" ref={orderRecovery} className={styles.refresh} disabled={query.isFetching || command.running} onClick={() => void query.refetch()}>{t('common.refresh')}</button>
    <button type="button" className={styles.refresh} disabled={command.running} onClick={command.command.retry}>{t('common.retry_operation')}</button></>;
  const conflictActions = <><button type="button" ref={orderRecovery} className={styles.refresh} disabled={query.isFetching} onClick={cancelOrder}>{t('pages.order_cancel')}</button>
    <button type="button" className={styles.refresh} disabled={query.isFetching} onClick={() => void restartOrder()}>{t('pages.order_restart')}</button></>;
  const refresh = <button type="button" className={styles.refresh} disabled={query.isFetching || Boolean(draft)} onClick={() => void query.refetch()}>
    <RefreshCw size={17} aria-hidden className={query.isFetching && query.data ? styles.spinning : undefined} />
    {t(query.isFetching && query.data ? 'pages.refreshing' : 'common.refresh')}
  </button>;
  const operationCopy = operationTarget && { position: operationTarget.index + 1, name: operationTarget.item.name || t('catalog.placement_name_missing'),
    action: t(operationTarget.visibility === 'hidden' ? 'catalog.hide' : 'catalog.show') };

  return <>
    <div className={styles.controls}><div className={styles.tabs}>
      {(['home', 'library'] as const).map(value => <button type="button" key={value} className={styles.tab} aria-label={t('catalog.' + value)} aria-pressed={slug === value} disabled={Boolean(draft)} onClick={() => onSelect(value)}>
        {t('catalog.' + value)}<span aria-hidden className={styles.count}>{slug === value && query.data ? query.data.page.items.length : '—'}</span>
      </button>)}
    </div><div className={styles.controlActions}>
      {!orderFailure && !(operationOrder && command.intent && !draft) && command.error !== 'conflict' && refresh}
      {draft && !orderFailure ? <><button type="button" className={styles.refresh} disabled={command.running} onClick={cancelOrder}>{t('pages.order_cancel')}</button>
        <button type="button" ref={orderAction} className={styles.refresh} disabled={locked || dragging || !changed || orderStale || orderFailure} onClick={() => setOrderConfirm(true)}>{t('pages.order_save')}</button></>
        : !draft && canOrder && <button type="button" ref={orderAction} className={styles.refresh} disabled={locked || query.isFetching || orderFailure || !access.catalogEditing} onClick={() => { if (page) beginOrder(page); }}>{t('pages.order_adjust')}</button>}
    </div></div>
    <div className={styles.overview}><h2>{draft ? t('pages.order_heading', { count: changed }) : <>{t('catalog.' + slug)}{query.data && <> · {t('pages.item_count', { count: query.data.page.items.length })}</>}</>}</h2><p>{t(draft ? 'pages.order_hint' : 'pages.order')}</p></div>
    {saved && <p className={styles.refreshStatus} role="status">{t('pages.order_saved')}</p>}
    {draft && orderStale && !orderConfirm && !orderFailure && <div className={styles.notice} role="alert"><p>{t('pages.order_stale')}</p><div className={styles.noticeActions}>{conflictActions}</div></div>}
    {query.isPending && <p className={styles.state} role="status">{t('common.loading')}</p>}
    {query.isError && <div className={styles.notice} role="alert"><p>{t('pages.load_error')}</p><button type="button" className={styles.refresh} disabled={query.isFetching} onClick={() => void query.refetch()}>{t('common.retry')}</button></div>}
    {query.isFetching && query.data && <p className={styles.refreshStatus} role="status">{t('pages.refreshing_copy')}</p>}
    {operationOrder && command.running && <div className={styles.notice} role="status">{t('pages.order_saving')}</div>}
    {!operationOrder && command.running && <div className={styles.notice} role="status"><div>{operationCopy && <p className={styles.noticeTitle}>{t('pages.operation_target', operationCopy)}</p>}<p>{t('pages.updating')}</p></div></div>}
    {operationOrder && command.error && command.error !== 'reload' && <Suspense fallback={<p role="status">{t('common.loading')}</p>}>
      <PageOrderNotice {...presentation} review={operationOrder} unknown={Boolean(command.intent)} error={command.error} page={t('catalog.' + slug)} actions={command.intent ? recoveryActions : conflictActions} />
    </Suspense>}
    {!operationOrder && command.error && <div className={styles.notice} role="alert">
      <div>{command.intent && operationCopy && <p className={styles.noticeTitle}>{t('pages.operation_target', operationCopy)}</p>}
        <p>{t(command.error === 'conflict' ? 'pages.conflict' : command.error === 'error' ? 'pages.operation_error' : 'common.' + command.error)}</p></div>
      {command.intent && <button type="button" className={styles.refresh} disabled={command.running} onClick={command.command.retry}>{t('common.retry_operation')}</button>}
      {command.error === 'conflict' && refresh}
    </div>}
    {draft ? <Suspense fallback={<p className={styles.state} role="status">{t('common.loading')}</p>}><PageOrderList {...presentation} renderVisibility={item => <PagePlacementVisibility item={item} />} renderMetadata={item => <><PagePlacementMetadata item={item} /><PageReferenceWarning item={item} /></>} review={draft} disabled={locked || orderStale || orderConfirm} onDragging={setDragging} onChange={items => setDraft(current => current ? { ...current, items } : current)} /></Suspense> : query.data && (query.data.page.items.length ? <ol className={styles.list} aria-label={t('pages.order_current')}>
      {query.data.page.items.map((item, index) => <PagePlacementRow key={item.itemId} item={item} index={index} locked={locked || orderFailure}
        pending={command.running && operationTarget?.item.itemId === item.itemId}
        onChange={(opener, fallback) => {
          returnFocus.current = opener; pendingFocus.current = fallback;
          setTarget({ item, index, visibility: item.visibility === 'public' ? 'hidden' : 'public', revision: query.data.page.revision });
        }} />)}
    </ol> : <p className={styles.state}>{t('pages.empty')}</p>)}
    <footer className={styles.footer}><div><p>{t(draft || operationOrder ? 'pages.order_scope' : 'pages.scope')}</p><p>{t('pages.confirm_hint')}</p></div></footer>
    {draft && orderConfirm && <Suspense fallback={<p role="status">{t('common.loading')}</p>}><PageOrderApproval {...presentation} review={draft} page={t('catalog.' + slug)} stale={orderStale}
      initialFocusRef={cancel} returnFocusRef={orderAction} closeDisabled={command.running} onClose={() => setOrderConfirm(false)}
      actions={orderStale ? conflictActions : <>
        <button type="button" ref={cancel} className={styles.refresh} disabled={command.running} onClick={() => setOrderConfirm(false)}>{t('pages.order_back')}</button>
        <button type="button" className={styles.refresh + ' ' + styles.confirm} disabled={locked || !changed} onClick={() => {
          const guard = adminWorkspace.capture();
          adminWorkspace.retain(orderKey, draft, guard); setOperationOrder(draft);
          void client.cancelQueries({ queryKey });
          command.command.run('/pages/' + slug + '/reorder', { itemIds: draft.items.map(item => item.itemId), expectedRevision: draft.revision }, 'POST', { ADMIN_PAGE_ITEM_IDENTITY_CONFLICT: 'order_identity', ADMIN_CATALOG_RECEIPT_LIMIT: 'order_capacity', ADMIN_CATALOG_IDEMPOTENCY_CONFLICT: 'order_error' });
        }}>{command.running ? <><RefreshCw size={16} className={styles.spinning} aria-hidden />{t('pages.order_saving_button')}</> : t('pages.order_confirm')}</button>
      </>} /></Suspense>}
    {target && <ModalDialog title={t('catalog.confirm_placement')} description={t('catalog.confirm_placement_copy')}
      headerContent={<div className={styles.target}><p className={styles.targetPage}>{t('catalog.' + slug)}</p>
        <strong>{target.index + 1} · {target.item.name || t('catalog.placement_name_missing')}</strong>
        <PagePlacementMetadata item={target.item} /><PageReferenceWarning item={target.item} />
        <p className={styles.transition}>{t('catalog.visibility_change', { current: t('field.' + target.item.visibility), next: t('field.' + target.visibility) })}</p>
      </div>} initialFocusRef={cancel} returnFocusRef={returnFocus} onClose={() => setTarget(null)}>
      <p className={styles.definitionScope}>{t('catalog.occurrence_copy')}</p>
      {target.visibility === 'public' && ['missing', 'unsupported'].includes(target.item.referenceStatus ?? '') && <p className={styles.warning}>{t('pages.reference_not_repaired')}</p>}
      {stale && <p className={styles.notice} role="alert">{t('pages.confirm_stale')}</p>}
      <div className={styles.dialogActions}>
        <button type="button" ref={cancel} className={styles.refresh} onClick={() => setTarget(null)}>{t('common.cancel')}</button>
        <button type="button" className={styles.refresh + ' ' + styles.confirm} disabled={locked || stale} onClick={() => {
          const guard = adminWorkspace.capture();
          adminWorkspace.retain(contextKey, target, guard); setOperationTarget(target);
          // The mutation disables its opener; Details remains an enabled focus destination.
          returnFocus.current = pendingFocus.current;
          void client.cancelQueries({ queryKey });
          command.command.run('/pages/' + slug + '/items/' + target.item.itemId, { expectedRevision: target.revision, visibility: target.visibility });
          setTarget(null);
        }}>{t(target.visibility === 'hidden' ? 'catalog.hide' : 'catalog.show')}</button>
      </div>
    </ModalDialog>}
  </>;
}

/** Administrator access is checked before mounting any private Page content. */
export const AdminPagesPage = () => <AdminGate><Pages /></AdminGate>;
